    ISNULL([datazone_2011_status], N''),
    CONVERT(date, NULLIF([inspection_date_parsed], ''), 23),
    CONVERT(date, NULLIF([lodgement_date_parsed], ''), 23),
    CONVERT(datetime2(0), NULLIF([created_at_parsed], ''), 120),
