    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(19,4), NULLIF([co2_emissions_current_num], ''))) = [co2_emissions_current_num] THEN CONVERT(decimal(19,4), [co2_emissions_current_num]) END,
    CASE WHEN CONVERT(varchar(40), CONVERT(decimal(19,4), NULLIF([co2_emiss_curr_per_floor_area_num], ''))) = [co2_emiss_curr_per_floor_area_num] THEN CONVERT(decimal(19,4), [co2_emiss_curr_per_floor_area_num]) END
FROM staging_epc_domestic;

DROP TABLE IF EXISTS staging_epc_domestic;

-- The two join routes.
CREATE INDEX IX_epc_domestic_uprn_osg ON epc_domestic ([uprn_osg], [inspection_date_parsed]) INCLUDE ([historic_flag]);
CREATE INDEX IX_epc_domestic_pc_norm ON epc_domestic ([pc_norm], [inspection_date_parsed]) INCLUDE ([uprn_sepcr], [historic_flag]);
